// ADR-135 T2: collectBranchState replays the stubbed command answers of tests/branch-state.test.mjs. Every expected value in
// bsCollectCases (the state, the checkpoint and the commands in their order) was produced by the Node collect of
// plugin/scripts/branch-state.mjs on 2026-11-01, over the same tables through a verbatim copy of that test file's runner(),
// so a disagreement here is a disagreement with Node. The subtests after the table run the real runner and real git.
package hooks

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
	"time"
)

type bsCollectCase struct {
	name, table, heads      string
	step, viewCost, startAt float64
	budget                  bool
	want, checkpoint, calls string
}

var bsStubTip = regexp.MustCompile(`^git rev-parse (?:@\{upstream\}|origin/)`)

// bsStubAnswer reads one answer of a stub table: a note only where the table gave one, as in JavaScript.
func bsStubAnswer(v any) bsAnswer {
	answer := bsAnswer{OK: isTrue(get(v, "ok")), Out: strOr(get(v, "out")), Budget: isTrue(get(v, "budget"))}
	if note := get(v, "note"); !isUndefined(note) {
		answer.Note = note
	}
	return answer
}

// bsStubRunner is tests/branch-state.test.mjs runner(): the first prefix that matches answers; a table that names no pushed
// tip answers one from the newest run its `gh run list` fake lists; anything else is "not ok".
func bsStubRunner(t *testing.T, tableJSON string) func([]string) bsAnswer {
	parsed, err := parseJSON(tableJSON)
	if err != nil {
		t.Fatalf("the stub table is not JSON: %v", err)
	}
	table, _ := parsed.([]any)
	prefix := func(entry any) string { pair, _ := entry.([]any); return strOr(pair[0]) }
	answer := func(entry any) any { pair, _ := entry.([]any); return pair[1] }
	tipOf := func() (bsAnswer, bool) {
		for _, entry := range table {
			p := prefix(entry)
			if !strings.HasPrefix("gh run list", p) && !strings.HasPrefix(p, "gh run list") {
				continue
			}
			listing := bsStubAnswer(answer(entry))
			if !listing.OK {
				return bsAnswer{}, false
			}
			rows, err := parseJSON(listing.Out)
			if err != nil {
				return bsAnswer{}, false
			}
			list, _ := rows.([]any)
			var newest any
			for _, r := range list {
				if truthy(r) && truthy(get(r, "headSha")) && isSafeInteger(get(r, "databaseId")) &&
					(newest == nil || get(r, "databaseId").(float64) > get(newest, "databaseId").(float64)) {
					newest = r
				}
			}
			if newest == nil {
				return bsAnswer{}, false
			}
			return bsAnswer{OK: true, Out: jsString(get(newest, "headSha"))}, true
		}
		return bsAnswer{}, false
	}
	namesTip := false
	for _, entry := range table {
		namesTip = namesTip || bsStubTip.MatchString(prefix(entry))
	}
	return func(argv []string) bsAnswer {
		line := strings.Join(argv, " ")
		for _, entry := range table {
			if strings.HasPrefix(line, prefix(entry)) {
				return bsStubAnswer(answer(entry))
			}
		}
		if !namesTip && bsStubTip.MatchString(line) {
			if tip, found := tipOf(); found {
				return tip
			}
		}
		return bsAnswer{Note: "no fake for: " + line}
	}
}

// TestBSCollectChild is the child process the real-runner subtests start: it says what it was asked to, and exits.
func TestBSCollectChild(t *testing.T) {
	switch os.Getenv("QH_BS_CHILD") {
	case "":
		return
	case "env":
		fmt.Print(os.Getenv("LC_ALL") + "|" + os.Getenv("GIT_OPTIONAL_LOCKS"))
	case "stdin":
		read, _ := io.ReadAll(os.Stdin)
		fmt.Printf("  [%s]\n", read)
	case "fail":
		fmt.Fprint(os.Stderr, "first line\nsecond line\n")
		os.Exit(3)
	case "sleep":
		time.Sleep(10 * time.Second)
	}
	os.Exit(0)
}

func TestBranchStateCollect(t *testing.T) {
	for _, c := range bsCollectCases {
		t.Run(c.name, func(t *testing.T) {
			stub := bsStubRunner(t, c.table)
			now := 0.0
			var calls []string
			checkpoint := ""
			inner := func(argv []string, opts bsOpts) bsAnswer {
				line := strings.Join(argv, " ")
				if opts.Input != "" {
					line += " <<" + stringify(opts.Input)
				}
				if opts.Timeout != 0 {
					line += " @" + jsNumber(float64(opts.Timeout)/float64(time.Millisecond))
				}
				calls = append(calls, line)
				now += c.step
				if strings.HasPrefix(strings.Join(argv, " "), "gh run view") {
					now += c.viewCost
				}
				return stub(argv)
			}
			clock := func() float64 { return now }
			run := bsRunner(inner)
			if c.budget {
				run = bsBudgeted(bsBudgetMs, inner, clock, "")
				now = c.startAt
			}
			var heads []string
			if listed, err := parseJSON(c.heads); err == nil && listed != nil {
				heads = []string{}
				for _, head := range listed.([]any) {
					heads = append(heads, head.(string))
				}
			}
			got := collectBranchState(run, func(state any) {
				calls = append(calls, "CHECKPOINT")
				checkpoint = stringify(state)
			}, clock, heads)
			if said := stringify(got); said != c.want {
				t.Errorf("state\n got: %s\nwant: %s", said, c.want)
			}
			if checkpoint != c.checkpoint {
				t.Errorf("checkpoint\n got: %s\nwant: %s", checkpoint, c.checkpoint)
			}
			if ran := strings.Join(calls, "\n"); ran != c.calls {
				t.Errorf("commands\n got: %s\nwant: %s", ran, c.calls)
			}
		})
	}

	t.Run("budgeted gives each command the remainder of one deadline", func(t *testing.T) {
		clock := 0.0
		var timeouts []time.Duration
		run := bsBudgeted(15000, func(argv []string, opts bsOpts) bsAnswer {
			timeouts = append(timeouts, opts.Timeout)
			return bsAnswer{OK: true, Out: "x"}
		}, func() float64 { return clock }, "")
		run([]string{"git", "status"}, bsOpts{})
		clock = 14000
		run([]string{"gh", "run", "list"}, bsOpts{})
		if len(timeouts) != 2 || timeouts[0] != 15*time.Second || timeouts[1] != time.Second {
			t.Fatalf("timeouts %v, want [15s 1s]: each command gets what is left, never a fresh 15s", timeouts)
		}
		clock = 20000
		spent := run([]string{"gh", "run", "view", "1"}, bsOpts{})
		if spent.OK || !spent.Budget || spent.Note != "budget of 15000ms spent before `gh run view 1`" || len(timeouts) != 2 {
			t.Fatalf("past the deadline: %+v after %d spawns, want a prevented, marked answer and no spawn", spent, len(timeouts))
		}
		long := bsBudgeted(bsBudgetMs*4, func(argv []string, opts bsOpts) bsAnswer {
			timeouts = append(timeouts, opts.Timeout)
			return bsAnswer{}
		}, func() float64 { return 0 }, "")
		if answered := long([]string{"gh"}, bsOpts{}); answered.Budget || timeouts[2] != 15*time.Second {
			t.Fatalf("a command that ran and failed is not a budget refusal (%+v), and one command is capped at 15s (%v)", answered, timeouts[2])
		}
		var cwd string
		bsBudgeted(bsBudgetMs, func(argv []string, opts bsOpts) bsAnswer { cwd = opts.Cwd; return bsAnswer{} },
			func() float64 { return 0 }, "/repo")([]string{"git"}, bsOpts{})
		if cwd != "/repo" {
			t.Fatalf("the budget's directory was not passed on: %q", cwd)
		}
	})

	child := func(t *testing.T, mode string) []string {
		t.Setenv("QH_BS_CHILD", mode)
		return []string{os.Args[0], "-test.run=^TestBSCollectChild$"}
	}

	t.Run("the real runner pins LC_ALL=C and leaves git's lock alone elsewhere", func(t *testing.T) {
		t.Setenv("LC_ALL", "lt_LT.UTF-8")
		t.Setenv("GIT_OPTIONAL_LOCKS", "1")
		read := bsShell(child(t, "env"), bsOpts{})
		if !read.OK || read.Out != "C|1" {
			t.Fatalf("%+v: want LC_ALL=C over the parent's lt_LT.UTF-8, and GIT_OPTIONAL_LOCKS untouched for a command that is not git", read)
		}
	})

	t.Run("the real runner gives stdin only when asked, trims, and reports a failure's first stderr line", func(t *testing.T) {
		given := bsShell(child(t, "stdin"), bsOpts{Input: "^abc\n"})
		if !given.OK || given.Out != "[^abc\n]" {
			t.Fatalf("given input: %+v", given)
		}
		empty := bsShell(child(t, "stdin"), bsOpts{})
		if !empty.OK || empty.Out != "[]" {
			t.Fatalf("no input must read an empty stdin, never the parent's: %+v", empty)
		}
		failed := bsShell(child(t, "fail"), bsOpts{})
		if failed.OK || failed.Out != "" || failed.Note != "first line" {
			t.Fatalf("a failure: %+v, want not ok with the first stderr line", failed)
		}
		started := time.Now()
		slow := bsShell(child(t, "sleep"), bsOpts{Timeout: 300 * time.Millisecond})
		if slow.OK || !strings.Contains(jsString(slow.note()), "ETIMEDOUT") || time.Since(started) > 8*time.Second {
			t.Fatalf("the timeout was not honoured: %+v after %v", slow, time.Since(started))
		}
		absent := bsShell([]string{"definitely-not-a-binary-here-9a3f", "--version"}, bsOpts{})
		if absent.OK || absent.Out != "" || jsString(absent.note()) == "" || nullish(absent.note()) {
			t.Fatalf("an absent binary must be an answer with a reason: %+v", absent)
		}
	})

	gitEnv := func(t *testing.T) string {
		if _, err := exec.LookPath("git"); err != nil {
			t.Fatalf("git is not on PATH: %v", err)
		}
		home := t.TempDir()
		t.Setenv("HOME", home)
		t.Setenv("GIT_CONFIG_GLOBAL", filepath.Join(home, "gitconfig"))
		t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
		return home
	}

	t.Run("git is run with LC_ALL=C and GIT_OPTIONAL_LOCKS=0", func(t *testing.T) {
		dir := gitEnv(t)
		t.Setenv("LC_ALL", "lt_LT.UTF-8")
		t.Setenv("GIT_OPTIONAL_LOCKS", "1")
		read := bsShell([]string{"git", "-c", `alias.qhenv=!printf '%s|%s' "$LC_ALL" "$GIT_OPTIONAL_LOCKS"`, "qhenv"}, bsOpts{Cwd: dir})
		if !read.OK || read.Out != "C|0" {
			t.Fatalf("%+v: want C|0", read)
		}
	})

	t.Run("an untagged repository under a non-English locale is positively untagged, through real git", func(t *testing.T) {
		gitEnv(t)
		t.Setenv("LANG", "de_DE.UTF-8")
		t.Setenv("LC_ALL", "de_DE.UTF-8")
		t.Setenv("LANGUAGE", "de")
		dir := t.TempDir()
		for _, argv := range [][]string{{"init", "-q"}, {"-c", "user.name=t", "-c", "user.email=t@example.invalid", "-c", "commit.gpgsign=false",
			"commit", "-q", "--allow-empty", "-m", "first"}} {
			if out, err := exec.Command("git", append([]string{"-C", dir}, argv...)...).CombinedOutput(); err != nil {
				t.Fatalf("git %v: %v\n%s", argv, err, out)
			}
		}
		started := float64(time.Now().UnixMilli())
		clock := func() float64 { return float64(time.Now().UnixMilli()) - started }
		collect := func() any {
			return collectBranchState(bsBudgeted(bsBudgetMs, bsShell, clock, dir), func(any) {}, clock, nil)
		}
		state := collect()
		if !isTrue(get(state, "looked")) || get(state, "tag") != nil || get(state, "releaseBlocked") != nil ||
			!strict(dig(state, "ci", "note"), bsNoGitHubNote) || !strict(get(state, "dirty"), 0.0) {
			t.Fatalf("an untagged, remote-less repository: %s", stringify(state))
		}
		if out, err := exec.Command("git", "-C", dir, "tag", "v1").CombinedOutput(); err != nil {
			t.Fatalf("git tag: %v\n%s", err, out)
		}
		tagged := collect()
		if !strict(get(tagged, "tag"), "v1") || !strict(get(tagged, "shippedSinceTag"), 0.0) || get(tagged, "releaseBlocked") != nil {
			t.Fatalf("a tagged repository: %s", stringify(tagged))
		}
	})

	t.Run("gitDir asks git, and answers null rather than guessing a directory", func(t *testing.T) {
		answer := func(a bsAnswer) bsRunner { return func([]string, bsOpts) bsAnswer { return a } }
		if got := bsGitDir(answer(bsAnswer{OK: true, Out: "/somewhere/.git"})); got != "/somewhere/.git" {
			t.Fatalf("got %v", got)
		}
		if got := bsGitDir(answer(bsAnswer{Note: "not a repository"})); got != nil {
			t.Fatalf("a failure must be nil, got %v", got)
		}
		if got := bsGitDir(answer(bsAnswer{OK: true})); got != nil {
			t.Fatalf("an empty answer is not a path, got %v", got)
		}
	})

	t.Run("reviewedHeads reads the covering rows of reviews.jsonl, and nothing else", func(t *testing.T) {
		dir := t.TempDir()
		if heads := bsReviewedHeads(dir); heads != nil {
			t.Fatalf("no ledger is nil, not an empty list: %v", heads)
		}
		a, c := strings.Repeat("a", 40), strings.Repeat("c", 64)
		rows := []string{`{"status":"clean","head":"` + a + `"}`, `{"status":"killed","head":"` + strings.Repeat("b", 40) + `"}`, "not json",
			`{"status":"unparsed","head":"` + strings.Repeat("d", 40) + `"}`, `{"status":"blocking","head":"abc123"}`,
			`{"status":"blocking","head":"` + c + `"}`, `{"status":"evidence-limited","head":"` + a + `"}`, `{"status":"clean","head":null}`,
			`{"status":"clean","head":"` + strings.Repeat("A", 40) + `"}`}
		if err := os.WriteFile(filepath.Join(dir, bsReviewsFile), []byte(strings.Join(rows, "\n")), 0o600); err != nil {
			t.Fatal(err)
		}
		if heads := bsReviewedHeads(dir); stringify(heads) != stringify([]string{a, c}) {
			t.Fatalf("got %v, want [a…, c…]", heads)
		}
		if err := os.WriteFile(filepath.Join(dir, bsReviewsFile), []byte("not json\n"), 0o600); err != nil {
			t.Fatal(err)
		}
		if heads := bsReviewedHeads(dir); heads == nil || len(heads) != 0 {
			t.Fatalf("a ledger with no covering row is an empty list, not nil: %#v", heads)
		}
	})
}

